'use strict';

/**
 * Least-recently-used cache.
 *   new LRU({ max, ttl, now, onEvict })
 *     max       max number of entries (default 100)
 *     ttl       default time-to-live in ms; entries expire when now() - born >= ttl
 *     now       clock function, default () => Date.now()
 *     onEvict   callback (key, value, reason) on eviction; reason is
 *               'capacity' | 'deleted' | 'expired' | 'replaced'
 * get(k) marks the entry as most recently used; peek(k) reads without refreshing;
 * set(k, v, { ttl }) inserts or replaces; delete(k); has(k); size; keys().
 */
class LRU {
  constructor(opts = {}) {
    this.max = opts.max === undefined ? 100 : opts.max;
    if (!Number.isInteger(this.max) || this.max < 1) throw new RangeError('max must be a positive integer');
    this.ttl = opts.ttl;
    this.now = opts.now || (() => Date.now());
    this.onEvict = opts.onEvict;
    this.map = new Map(); // key -> { value, born, ttl }
  }

  get size() {
    this.purgeExpired();
    return this.map.size;
  }

  has(key) {
    const e = this.map.get(key);
    if (!e) return false;
    if (this.isExpired(e)) { this.remove(key, e, 'expired'); return false; }
    return true;
  }

  get(key) {
    const e = this.map.get(key);
    if (!e) return undefined;
    if (this.isExpired(e)) { this.remove(key, e, 'expired'); return undefined; }
    this.map.delete(key);
    this.map.set(key, e);
    return e.value;
  }

  /** Read without refreshing recency. */
  peek(key) {
    const e = this.map.get(key);
    if (!e) return undefined;
    if (this.isExpired(e)) { this.remove(key, e, 'expired'); return undefined; }
    return e.value;
  }

  set(key, value, opts = {}) {
    const existing = this.map.get(key);
    if (existing) {
      this.remove(key, existing, this.isExpired(existing) ? 'expired' : 'replaced');
    }
    const ttl = opts.ttl !== undefined ? opts.ttl : this.ttl;
    this.map.set(key, { value, born: this.now(), ttl });
    while (this.map.size > this.max) {
      const oldest = this.map.keys().next().value;
      const e = this.map.get(oldest);
      this.remove(oldest, e, this.isExpired(e) ? 'expired' : 'capacity');
    }
    return this;
  }

  delete(key) {
    const e = this.map.get(key);
    if (!e) return false;
    this.remove(key, e, 'deleted');
    return true;
  }

  /** Keys from least to most recently used (expired entries are purged). */
  keys() {
    this.purgeExpired();
    return [...this.map.keys()];
  }

  isExpired(e) {
    return e.ttl !== undefined && this.now() - e.born >= e.ttl;
  }

  purgeExpired() {
    for (const [key, e] of this.map) {
      if (this.isExpired(e)) this.remove(key, e, 'expired');
    }
  }

  remove(key, e, reason) {
    this.map.delete(key);
    if (typeof this.onEvict === 'function') this.onEvict(key, e.value, reason);
  }
}

module.exports = { LRU };
```

